@Test func everyFeedFixtureDecodesAndShapesRows() throws {
    for f in fixtures {
        let v = try dec(JSONValue.self, f.json)
        if f.rows >= 0 { #expect(v.tableRows?.count == f.rows, "\(f.path) (\(f.kind))") }
        else { #expect(v.tableRows == nil && v.object != nil, "\(f.path) (\(f.kind))") }
    }
}

@Test func feedsCoverEveryFixture() {
    let all: [SchedFeed] = [SchedFeed.placement, SchedFeed.classesAndBudgets, SchedFeed.quotasAndGovernance, SchedFeed.autoscaling, SchedFeed.devicesAndHosts].flatMap { $0 }
    #expect(Set(all.map { $0.id }) == Set(fixtures.map { $0.path }))
}

